import heapq

def match(orders):
    buy_heap = []   # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    orders_info = {}  # id -> {'side','price','qty','active'}
    trades = []
    seq_counter = 0

    def clean_buy_heap():
        while buy_heap and not orders_info[buy_heap[0][2]]['active']:
            heapq.heappop(buy_heap)

    def clean_sell_heap():
        while sell_heap and not orders_info[sell_heap[0][2]]['active']:
            heapq.heappop(sell_heap)

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            if oid in orders_info and orders_info[oid]['active']:
                orders_info[oid]['active'] = False
            continue

        oid = order[1]
        side = order[2]

        if typ == 'market':
            price = None
            qty = order[3]
        else:
            price = order[3]
            qty = order[4]

        remaining = qty

        if side == 'buy':
            while remaining > 0:
                clean_sell_heap()
                if not sell_heap:
                    break
                top_price, top_seq, top_id = sell_heap[0]
                if typ != 'market' and top_price > price:
                    break
                sell_order = orders_info[top_id]
                trade_qty = min(remaining, sell_order['qty'])
                trades.append([oid, top_id, top_price, trade_qty])
                remaining -= trade_qty
                sell_order['qty'] -= trade_qty
                if sell_order['qty'] == 0:
                    sell_order['active'] = False
                    heapq.heappop(sell_heap)
        else:
            while remaining > 0:
                clean_buy_heap()
                if not buy_heap:
                    break
                neg_price, top_seq, top_id = buy_heap[0]
                top_price = -neg_price
                if typ != 'market' and top_price < price:
                    break
                buy_order = orders_info[top_id]
                trade_qty = min(remaining, buy_order['qty'])
                trades.append([top_id, oid, top_price, trade_qty])
                remaining -= trade_qty
                buy_order['qty'] -= trade_qty
                if buy_order['qty'] == 0:
                    buy_order['active'] = False
                    heapq.heappop(buy_heap)

        if typ == 'limit':
            if remaining > 0:
                orders_info[oid] = {'side': side, 'price': price, 'qty': remaining, 'active': True}
                seq_counter += 1
                if side == 'buy':
                    heapq.heappush(buy_heap, (-price, seq_counter, oid))
                else:
                    heapq.heappush(sell_heap, (price, seq_counter, oid))
            else:
                orders_info[oid] = {'side': side, 'price': price, 'qty': 0, 'active': False}
        else:
            # ioc or market: remainder discarded, order does not rest
            orders_info[oid] = {'side': side, 'price': price, 'qty': remaining, 'active': False}

    return trades

